#!/usr/bin/env python3
"""Search for agents matching a query."""
import json
import sys
from pathlib import Path

REGISTRY_ROOT = Path(__file__).parent.parent
INDEX_FILE = REGISTRY_ROOT / "index.json"

def score_agent(agent, query):
    """Calculate relevance score (0.0-1.0)."""
    query_lower = query.lower()
    words = query_lower.split()
    score = 0.0

    # Check name match
    name_lower = agent["name"].lower()
    if query_lower in name_lower:
        score += 0.5
    elif any(w in name_lower for w in words):
        score += 0.3

    # Check category match
    category_lower = agent["category"].lower()
    if query_lower in category_lower:
        score += 0.3
    elif any(w in category_lower for w in words):
        score += 0.2

    # Check description match
    desc_lower = agent["description"].lower()
    if query_lower in desc_lower:
        score += 0.2
    elif any(w in desc_lower for w in words):
        score += 0.1

    return min(score, 1.0)

def main():
    if len(sys.argv) < 2:
        print("Usage: search.py <query>")
        sys.exit(1)

    query = " ".join(sys.argv[1:])

    with open(INDEX_FILE) as f:
        index = json.load(f)

    results = []
    for agent in index["agents"]:
        score = score_agent(agent, query)
        if score > 0:
            results.append((score, agent))

    results.sort(key=lambda x: -x[0])

    print(f"Search results for: '{query}'")
    print("-" * 60)
    if results:
        for score, agent in results:
            print(f"  [{score:.1f}] {agent['name']}")
            print(f"      Category: {agent['category']}")
            print(f"      {agent['description']}")
            print()
    else:
        print("  No matching agents found.")

if __name__ == "__main__":
    main()
